    /// cascade.
    #[must_use]
    pub const fn axes_eq(self, other: Self) -> [bool; Self::FIELD_COUNT] {
        let below = self.axes_leq(other);
        let above = self.axes_geq(other);
        [
            below[0] && above[0],
            below[1] && above[1],
            below[2] && above[2],
            below[3] && above[3],
            below[4] && above[4],
            below[5] && above[5],
        ]
    }

    /// Per-axis pointwise `!=` mask across the six ceilings — the ATOMIC
