    #[must_use]
    pub const fn is_lower_bound_of(self, postures: &[Self]) -> bool {
        let mut i = 0;
        while i < postures.len() {
            if !self.leq(postures[i]) {
                return false;
            }
            i += 1;
        }
        true
    }

    /// Boolean `leq`-conjunction across a slice of postures — every operand
