    pub const fn bottom_is_majority(self) -> bool {
        self.count_bottom_axes() > self.count_top_axes()
    }

    /// Whole-posture TOP-STRICT-MAJORITY predicate —
    /// `self.top_is_majority()` holds iff the top-arm tally STRICTLY
