    pub const fn top_is_majority(self) -> bool {
        self.count_top_axes() > self.count_bottom_axes()
    }

    /// Whole-posture ATOMICALLY-BALANCED predicate —
    /// `self.is_atomically_balanced()` holds iff the bottom-arm tally
