    pub const fn atomic_then_axial_ordering(self) -> Ordering {
        match self.atomic_ordering() {
            Ordering::Equal => self.axial_ordering(),
            Ordering::Greater => Ordering::Greater,
            Ordering::Less => Ordering::Less,
        }
    }

