    pub const fn bottom_axis_is_nearly_saturated(self) -> Option<bool> {
        match self.count_bottom_axes() {
            0 => None,
            c => Some(c == Self::FIELD_COUNT - 1),
        }
    }

    /// Whole-posture NEARLY-SATURATED-OF-TOP predicate —
