    /// new per-axis scan, no allocation.
    #[must_use]
    pub const fn bottom_axis_is_at_most_half_saturated(self) -> Option<bool> {
        match self.count_bottom_axes() {
            0 => None,
            c => Some(c * 2 <= Self::FIELD_COUNT),
        }
    }

