        assert_eq!(e.max_cache_entries(), DEFAULT_MAX_CACHE_ENTRIES);
        assert_eq!(e.max_expansion_size(), DEFAULT_MAX_EXPANSION_SIZE);
        assert_eq!(e.max_macro_body_size(), DEFAULT_MAX_MACRO_BODY_SIZE);
