        const _: () = assert!(EMPTY_RESOURCE_LIMITS.has_bottom_axis());
        const _: () = assert!(!UNBOUNDED_RESOURCE_LIMITS.has_bottom_axis());
        const _: () = assert!(!DEFAULT_RESOURCE_LIMITS.has_bottom_axis());
