    #[test]
    fn resource_limits_fields_evaluates_at_compile_time_via_const_fn() {
        // Const-fn pin — the `fields` fusion is `const fn` so a caller
        // can pin a preset's per-axis paired projection at compile
        // time. Sibling of the const-fn evaluability pins on
        // `field_values` / `from_field_values` / `strictest` /
        // `most_permissive` / `leq` / etc. on the `ResourceLimits`
        // algebra. Round-trip pins the three shipped presets in const
        // context so a const-fn body drift that dropped the fusion
        // invariant fires at compile time via one of the paired-value
        // assertions below.
        const EMPTY_PAIRS: [(&str, usize); ResourceLimits::FIELD_COUNT] =
            EMPTY_RESOURCE_LIMITS.fields();
        const UNBOUNDED_PAIRS: [(&str, usize); ResourceLimits::FIELD_COUNT] =
            UNBOUNDED_RESOURCE_LIMITS.fields();
        const DEFAULT_PAIRS: [(&str, usize); ResourceLimits::FIELD_COUNT] =
            DEFAULT_RESOURCE_LIMITS.fields();
        // Per-axis discrimination pins in const context — the paired
        // FUSION recovers the canonical `FIELD_NAMES[i]` on every
        // preset at every axis (names are preset-invariant), and the
        // value-half discriminates the three shipped presets at the
        // per-axis level.
        const _: () = assert!(EMPTY_PAIRS[0].1 == 0);
        const _: () = assert!(EMPTY_PAIRS[5].1 == 0);
        const _: () = assert!(UNBOUNDED_PAIRS[0].1 == usize::MAX);
        const _: () = assert!(UNBOUNDED_PAIRS[5].1 == usize::MAX);
        const _: () = assert!(DEFAULT_PAIRS[0].1 == DEFAULT_MAX_EXPANSION_DEPTH);
        const _: () = assert!(DEFAULT_PAIRS[5].1 == DEFAULT_MAX_MACRO_ARITY);
    }

    #[test]
    fn resource_limits_fields_discriminate_hand_authored_postures() {
        // Discrimination pin — the paired FUSION discriminates the
        // two hand-authored asymmetric postures at every axis via the
        // value-half (the name-half is preset-invariant across postures
        // so it does NOT contribute to per-posture discrimination).
        // Rules out a hypothetical fusion bug that returned a constant
        // paired array regardless of the receiver posture. Sibling of
        // `resource_limits_field_values_discriminate_hand_authored_postures`
        // one PROJECTION-KIND axis over on the (name-only, value-only,
        // name+value) projection triple.
        let mid = HAND_AUTHORED_MID_POSTURE.fields();
        let other = HAND_AUTHORED_OTHER_POSTURE.fields();
        for (mid_pair, other_pair) in mid.iter().zip(other.iter()) {
            assert_eq!(mid_pair.0, other_pair.0);
            assert_ne!(mid_pair.1, other_pair.1);
        }
    }

    #[test]
    fn resource_limits_field_count_evaluates_at_compile_time_via_const() {
        // Const-eval pin — `Self::FIELD_COUNT` is a `pub const usize`
        // so a caller can pin the cardinality at compile time. Peer
        // of the const-fn evaluability pins on every method in the
        // `ResourceLimits` algebra. A regression that redeclared the
        // constant as a non-`const` `static` or a `fn` returning
        // `usize` breaks the const-context pin below.
        const _: usize = ResourceLimits::FIELD_COUNT;
        const _: () = assert!(ResourceLimits::FIELD_COUNT == 6);
    }

    #[test]
    fn resource_limits_field_names_evaluates_at_compile_time_via_const() {
        // Const-eval pin — `Self::FIELD_NAMES` is a `pub const
        // [&'static str; FIELD_COUNT]` so a caller can pin the
        // closed-set ALL array at compile time. Peer of the
        // `FIELD_COUNT` const-eval pin above one PROJECTION axis
        // over.
        const _: [&str; ResourceLimits::FIELD_COUNT] = ResourceLimits::FIELD_NAMES;
        const _: () = assert!(ResourceLimits::FIELD_NAMES.len() == ResourceLimits::FIELD_COUNT);
    }

    #[test]
    fn resource_limits_field_values_evaluates_at_compile_time_via_const_fn() {
        // Const-fn pin — the `field_values` projection is `const
        // fn` so a caller can pin a preset's per-axis projection at
        // compile time. Sibling of the const-fn evaluability pins on
        // `strictest` / `most_permissive` / `leq` / etc. on the
        // `ResourceLimits` algebra.
        const EMPTY_VALUES: [usize; ResourceLimits::FIELD_COUNT] =
            EMPTY_RESOURCE_LIMITS.field_values();
        const UNBOUNDED_VALUES: [usize; ResourceLimits::FIELD_COUNT] =
            UNBOUNDED_RESOURCE_LIMITS.field_values();
        const DEFAULT_VALUES: [usize; ResourceLimits::FIELD_COUNT] =
            DEFAULT_RESOURCE_LIMITS.field_values();
        // Discrimination pin: the three preset projections are
        // pairwise distinct, so a const-fn body drift that collapsed
        // any two projections fires here.
        const _: () = assert!(EMPTY_VALUES[0] != UNBOUNDED_VALUES[0]);
        const _: () = assert!(EMPTY_VALUES[0] != DEFAULT_VALUES[0]);
        const _: () = assert!(DEFAULT_VALUES[0] != UNBOUNDED_VALUES[0]);
        // Preset-shape pins: bottom projects to `[0; N]`, top to
        // `[usize::MAX; N]`.
        const _: () = assert!(EMPTY_VALUES[0] == 0);
        const _: () = assert!(EMPTY_VALUES[5] == 0);
        const _: () = assert!(UNBOUNDED_VALUES[0] == usize::MAX);
        const _: () = assert!(UNBOUNDED_VALUES[5] == usize::MAX);
    }

    /// Test-local SPARSE bottom-axis posture — bottom axes at positions
    /// `(0, 2, 5)`, non-bottom at positions `(1, 3, 4)`. Span = 6 (from
    /// 0 to 5 inclusive), count = 3, gap = 3. Chosen so the (span, count,
    /// gap) triple is (6, 3, 3), witnessing the LOAD-BEARING sparsity
    /// mid-value neither the SATURATED preset pins nor a CONTIGUOUS
    /// pin can pin — a proper interior point of the CONTIGUOUS-vs-SPARSE
    /// discriminator.
    const SPARSE_BOTTOM_POSTURE: ResourceLimits = ResourceLimits {
        max_expansion_depth: 0, // bottom at 0
        max_cache_entries: 17,
        max_expansion_size: 0, // bottom at 2
        max_macro_body_size: 23,
        max_registered_macros: 29,
        max_macro_arity: 0, // bottom at 5
    };

    /// Test-local CONTIGUOUS-run bottom-axis posture — bottom axes at
    /// positions `(1, 2, 3)`, non-bottom at positions `(0, 4, 5)`. Span
    /// = 3, count = 3, gap = 0. The CONTIGUOUS DISCRIMINATOR at a non-
    /// preset non-saturated bracket, pinning that the (span, count, gap)
    /// = (3, 3, 0) triple can be achieved at an INTERIOR position rather
    /// than only at the saturated pole preset EMPTY.
    const CONTIGUOUS_INTERIOR_BOTTOM_POSTURE: ResourceLimits = ResourceLimits {
        max_expansion_depth: 41,
        max_cache_entries: 0,   // bottom at 1
        max_expansion_size: 0,  // bottom at 2
        max_macro_body_size: 0, // bottom at 3
        max_registered_macros: 47,
        max_macro_arity: 53,
    };

    /// Test-local ENDPOINTS-ONLY bottom-axis posture — bottom axes at
    /// positions `(0, 5)` only, non-bottom at `(1, 2, 3, 4)`. Span = 6,
    /// count = 2, gap = 4. The MAXIMAL SPARSE case on FIELD_COUNT = 6:
    /// the two-endpoint bottom-axis set with all interior positions
    /// non-bottom saturates the SPARSITY at `FIELD_COUNT - 2 = 4`. Pins
    /// the tight upper bound of the GAP range at `FIELD_COUNT - count`.
    const ENDPOINTS_ONLY_BOTTOM_POSTURE: ResourceLimits = ResourceLimits {
        max_expansion_depth: 0, // bottom at 0
        max_cache_entries: 59,
        max_expansion_size: 61,
        max_macro_body_size: 67,
        max_registered_macros: 71,
        max_macro_arity: 0, // bottom at 5
    };

    #[test]
    fn resource_limits_bottom_axis_gap_count_preset_pins_saturate_at_contiguous_and_absent() {
        // Preset pins — the SATURATED-bottom-pole preset EMPTY packs all
        // six axes into positions `[0, 5]`; span = 6 = count so gap = 0
        // (the CONTIGUOUS pole). The absent-bottom presets UNBOUNDED and
        // DEFAULT and both hand-authored postures carry no bottom axis;
        // gap = None.
        assert_eq!(EMPTY_RESOURCE_LIMITS.bottom_axis_gap_count(), Some(0));
        assert_eq!(UNBOUNDED_RESOURCE_LIMITS.bottom_axis_gap_count(), None);
        assert_eq!(DEFAULT_RESOURCE_LIMITS.bottom_axis_gap_count(), None);
        assert_eq!(HAND_AUTHORED_MID_POSTURE.bottom_axis_gap_count(), None);
        assert_eq!(HAND_AUTHORED_OTHER_POSTURE.bottom_axis_gap_count(), None);
    }

    #[test]
    fn resource_limits_top_axis_gap_count_preset_pins_saturate_at_contiguous_and_absent() {
        // Preset pins dual — the SATURATED-top-pole preset UNBOUNDED
        // packs all six axes at `usize::MAX` across positions `[0, 5]`;
        // span = 6 = count so gap = 0. The absent-top presets EMPTY and
        // DEFAULT and both hand-authored postures carry no top axis; gap
        // = None.
        assert_eq!(UNBOUNDED_RESOURCE_LIMITS.top_axis_gap_count(), Some(0));
        assert_eq!(EMPTY_RESOURCE_LIMITS.top_axis_gap_count(), None);
        assert_eq!(DEFAULT_RESOURCE_LIMITS.top_axis_gap_count(), None);
        assert_eq!(HAND_AUTHORED_MID_POSTURE.top_axis_gap_count(), None);
        assert_eq!(HAND_AUTHORED_OTHER_POSTURE.top_axis_gap_count(), None);
    }

    #[test]
    fn resource_limits_atomic_gap_count_saturation_pole_partitions_into_contiguous_and_absent() {
        // CROSS-CELL SATURATION contrast — the two saturated pole presets
        // each pin (Some(0), None) on their (same-cell, dual-cell) GAP
        // pair. The saturated pole is UNIFORMLY CONTIGUOUS on its own cell
        // and UNIFORMLY ABSENT on the dual cell. Substrate-level
        // consistency pin against any future preset-drift.
        assert_eq!(EMPTY_RESOURCE_LIMITS.bottom_axis_gap_count(), Some(0));
        assert_eq!(EMPTY_RESOURCE_LIMITS.top_axis_gap_count(), None);
        assert_eq!(UNBOUNDED_RESOURCE_LIMITS.top_axis_gap_count(), Some(0));
        assert_eq!(UNBOUNDED_RESOURCE_LIMITS.bottom_axis_gap_count(), None);
    }

    #[test]
    fn resource_limits_bottom_axis_gap_count_equals_span_minus_count_on_every_shipped_posture() {
        // FIRST-LAST-COUNT-DERIVATION identity — the projection is
        // structurally `span - count` when span is Some, or None
        // otherwise. Pinned across every shipped preset + hand-authored +
        // test-local posture so a future rewrite of any of the three
        // underlying projections that silently drifts from the composition
        // contract fires this pin.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            let expected = a
                .bottom_axis_index_span()
                .map(|w| w - a.count_bottom_axes());
            assert_eq!(
                a.bottom_axis_gap_count(),
                expected,
                "gap = span - count identity failed on {a:?}",
            );
        }
    }

