        // trichotomy leg.
        assert!(!EMPTY_RESOURCE_LIMITS.is_axially_balanced());
        assert!(!UNBOUNDED_RESOURCE_LIMITS.is_axially_balanced());
        assert!(!DEFAULT_RESOURCE_LIMITS.is_axially_balanced());
