    #[test]
    fn resource_limits_atomic_ordering_equals_atomic_signed_skew_cmp_zero() {
        // ATOMIC SIGNED-CARDINAL → SIGNUM bridge — LOAD-BEARING
        // structural pin. `atomic_signed_skew().cmp(&0)` reads the SIGN
        // of the atomic SIGNED CARDINAL reading as the same `Ordering`
        // sum this atomic SIGNUM-TRICHOTOMY reading returns directly.
        // Pins the atomic SIGNUM exit as the MAGNITUDE-STRIPPED peer
        // of the atomic SIGNED-CARDINAL reading one PROJECTION-KIND
        // axis over: the atomic SIGNED reading carries the (arm,
        // magnitude) pair as one `isize`; the atomic SIGNUM reading
        // carries the (arm) fact alone as one [`Ordering`]. Mirror of
        // the `axial_ordering() == axial_signed_skew().cmp(&0)`
        // bridge one CELL-KIND axis over on the compound (polar,
        // interior) tally pair.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            assert_eq!(
                a.atomic_ordering(),
                a.atomic_signed_skew().cmp(&0),
                "atomic_ordering() != atomic_signed_skew().cmp(&0) on {a:?}",
            );
        }
    }

    #[test]
    fn resource_limits_atomic_ordering_partitions_every_posture_into_exactly_one_leg() {
        // ATOMIC TRICHOTOMY EXHAUSTIVENESS pin — LOAD-BEARING
        // structural pin. Every posture returns EXACTLY ONE of the
        // three [`Ordering`] variants (Less, Equal, Greater), and the
        // returned variant matches ONE of the three atomic boolean-
        // partition legs (top_is_majority, is_atomically_balanced,
        // bottom_is_majority). Proved structurally by rustc's `match`
        // exhaustiveness: any missing arm here is a compile error, so
        // the pin is a TYPE-level theorem of the atomic SIGNUM ↔
        // atomic boolean-partition isomorphism.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            let matches_partition_leg = match a.atomic_ordering() {
                Ordering::Greater => a.bottom_is_majority(),
                Ordering::Less => a.top_is_majority(),
                Ordering::Equal => a.is_atomically_balanced(),
            };
            assert!(
                matches_partition_leg,
                "atomic_ordering() leg mismatches atomic boolean partition on {a:?}",
            );
        }
    }

    #[test]
    fn resource_limits_atomic_ordering_partition_is_surjective_onto_fixture_set() {
        // ATOMIC SIGNUM SURJECTIVITY pin — LOAD-BEARING structural
        // pin. All three [`Ordering`] variants are reached across the
        // eight-fixture posture set: `Greater` at the bottom-uniform
        // preset arm (EMPTY) plus all three truly-mixed bottom-
        // carrying fixtures (SPARSE_BOTTOM, CONTIGUOUS_INTERIOR_BOTTOM,
        // ENDPOINTS_ONLY_BOTTOM); `Less` at the top-uniform preset
        // arm alone (UNBOUNDED); `Equal` at the three interior-uniform
        // preset postures (DEFAULT + both hand-authored) whose atomic
        // tally sits at (0, 0). Prevents a future atomic SIGNUM
        // regression that silently collapses the three-leg partition
        // onto a two-leg codomain — every leg has a fixture witness.
        // Contrasts with `axial_ordering`'s coverage which reaches
        // `Greater` on only the two saturated-polar preset arms and
        // `Equal` on only the two truly-mixed 3-3 fixtures — the
        // atomic reading redistributes the fixtures across the SIGNUM
        // legs per the LOAD-BEARING CELL-KIND contrast.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        let mut saw_greater = false;
        let mut saw_less = false;
        let mut saw_equal = false;
        for a in postures {
            match a.atomic_ordering() {
                Ordering::Greater => saw_greater = true,
                Ordering::Less => saw_less = true,
                Ordering::Equal => saw_equal = true,
            }
        }
        assert!(saw_greater, "no fixture reached Ordering::Greater leg");
        assert!(saw_less, "no fixture reached Ordering::Less leg");
        assert!(saw_equal, "no fixture reached Ordering::Equal leg");
    }

    #[test]
    fn resource_limits_atomic_ordering_cell_kind_split_from_axial_ordering_on_uniform_fixtures() {
        // CELL-KIND (ATOMIC vs COMPOUND) discriminating contrast pin —
        // LOAD-BEARING structural pin. The five uniform preset
        // fixtures partition the (axial_ordering, atomic_ordering) pair
        // into a distinct sequence of `Ordering` verdicts on each
        // side, witnessing the LOAD-BEARING CELL-KIND split at the
        // SIGNUM exit: the polar-uniform corner
        // (EMPTY=Greater/UNBOUNDED=Greater on compound) splits into
        // (EMPTY=Greater/UNBOUNDED=Less on atomic) via the arm-identity
        // discrimination the atomic reading recovers, while the
        // interior-uniform arm (all three=Less on compound) collapses
        // to (all three=Equal on atomic) via the atomic balance
        // corner both `count_bottom == 0 == count_top` reduces to. The
        // SIGNUM peer of the `axial_signed_skew` vs
        // `atomic_signed_skew` `{+6, -6, +6, -6, -6}` vs `{+6, -6, 0,
        // 0, 0}` SIGNED contrast one PROJECTION-KIND axis under —
        // this test carries the SAME contrast at the SIGNUM
        // codomain.
        assert_eq!(EMPTY_RESOURCE_LIMITS.axial_ordering(), Ordering::Greater);
        assert_eq!(EMPTY_RESOURCE_LIMITS.atomic_ordering(), Ordering::Greater);
        assert_eq!(
            UNBOUNDED_RESOURCE_LIMITS.axial_ordering(),
            Ordering::Greater,
        );
        assert_eq!(UNBOUNDED_RESOURCE_LIMITS.atomic_ordering(), Ordering::Less);
        assert_eq!(DEFAULT_RESOURCE_LIMITS.axial_ordering(), Ordering::Less);
        assert_eq!(DEFAULT_RESOURCE_LIMITS.atomic_ordering(), Ordering::Equal);
        assert_eq!(HAND_AUTHORED_MID_POSTURE.axial_ordering(), Ordering::Less);
        assert_eq!(HAND_AUTHORED_MID_POSTURE.atomic_ordering(), Ordering::Equal);
        assert_eq!(HAND_AUTHORED_OTHER_POSTURE.axial_ordering(), Ordering::Less);
        assert_eq!(
            HAND_AUTHORED_OTHER_POSTURE.atomic_ordering(),
            Ordering::Equal,
        );
    }

    #[test]
    fn resource_limits_atomic_ordering_evaluates_at_compile_time_via_const_fn() {
        // Const-fn pin on the ATOMIC SIGNUM-TRICHOTOMY reading — the
        // atomic [`Ordering`] verdict is evaluable in const context so
        // a caller can pin the exact atomic arm at compile time as a
        // build-break, including the LOAD-BEARING atomic-arm-identity
        // split (bottom-uniform=`Greater`, top-uniform=`Less`) the
        // compound `axial_ordering` merged onto the SAME `Greater`
        // cell. Uses `matches!` because `Ordering` is not `PartialEq`
        // in a `const`-comparable form on stable Rust — `matches!` is
        // the const-context-legal shape.
        const _: () = assert!(matches!(
            EMPTY_RESOURCE_LIMITS.atomic_ordering(),
            Ordering::Greater,
        ));
        const _: () = assert!(matches!(
            UNBOUNDED_RESOURCE_LIMITS.atomic_ordering(),
            Ordering::Less,
        ));
        const _: () = assert!(matches!(
            DEFAULT_RESOURCE_LIMITS.atomic_ordering(),
            Ordering::Equal,
        ));
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_preset_pins_axial_short_circuits_on_uniform_arms()
    {
        // AXIAL-THEN-ATOMIC LEXICOGRAPHIC SIGNUM preset pins — LOAD-
        // BEARING structural pin. Every preset posture is uniform on
        // some axial arm, so `axial_ordering()` fires a strict
        // (`Greater` or `Less`) verdict on every preset; the atomic
        // tiebreaker is NEVER consulted on the preset roster.
        // EMPTY (polar-uniform-bottom) and UNBOUNDED (polar-uniform-
        // top) both short-circuit at axial `Greater` — MERGING the
        // atomic arm identity that would split them at
        // (`Greater`/`Less`) on the standalone atomic reading —
        // matching `axial_ordering`'s COARSER polar-vs-interior
        // merger one PROJECTION-KIND axis under. The three interior-
        // uniform postures (DEFAULT + both hand-authored) all
        // short-circuit at axial `Less` — the atomic tiebreaker's
        // `Equal` verdict at their (0, 0) atomic tally is NOT
        // consulted, so their whole-posture verdict pins at `Less`
        // not `Equal`.
        assert_eq!(
            EMPTY_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            UNBOUNDED_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            DEFAULT_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            HAND_AUTHORED_MID_POSTURE.axial_then_atomic_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            HAND_AUTHORED_OTHER_POSTURE.axial_then_atomic_ordering(),
            Ordering::Less,
        );
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_truly_mixed_promotes_atomic_tiebreaker_on_axially_balanced_fixtures(
    ) {
        // LOAD-BEARING DISCRIMINATING-GAIN pin on truly-mixed
        // fixtures. The two 3-polar-3-interior fixtures fire axial
        // `Equal` (axially balanced), so the axial short-circuit
        // DOES NOT trigger and the atomic tiebreaker BECOMES the
        // whole-posture verdict: both fixtures carry 3 bottom + 0
        // top atomic tallies (atomic `Greater`), so the composed
        // reading fires `Greater` at each. This is the LOAD-BEARING
        // GAIN neither cell's SIGNUM alone can carry through ONE
        // `Ordering` — axial alone returns `Equal` (unhelpful arm
        // identity on axially-balanced fixtures); atomic alone
        // discards the axial-strict information; the composition
        // returns the atomic verdict as the whole-posture arm
        // identity on precisely the axially-balanced regime.
        // ENDPOINTS_ONLY has axial `Less` (2 polar + 4 interior),
        // so it short-circuits at axial and returns `Less` (atomic
        // `Greater` at 2 + 0 is DISCARDED).
        assert_eq!(
            SPARSE_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            ENDPOINTS_ONLY_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Less,
        );
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_agrees_with_axial_when_axial_non_equal() {
        // AXIAL-STRICT-AGREEMENT bridge — LOAD-BEARING structural
        // pin. On every posture whose axial SIGNUM reading fires a
        // strict verdict (`Greater` or `Less`), the composed reading
        // returns that same verdict — the atomic tiebreaker is NOT
        // consulted. Pins the composition as SHORT-CIRCUITING on the
        // first non-`Equal` argument, matching the std-canonical
        // [`Ordering::then`] semantics the const-fn body inlines.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            if a.axial_ordering() != Ordering::Equal {
                assert_eq!(
                    a.axial_then_atomic_ordering(),
                    a.axial_ordering(),
                    "axial_then_atomic_ordering() != axial_ordering() on axial-strict {a:?}",
                );
            }
        }
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_equals_atomic_when_axial_equal() {
        // AXIAL-EQUAL-USE-ATOMIC bridge — LOAD-BEARING structural
        // pin dual. On every posture whose axial SIGNUM reading
        // fires `Equal`, the composed reading defers to the atomic
        // SIGNUM verdict — the atomic reading BECOMES the whole-
        // posture verdict on the axial-balanced regime. Complements
        // the axial-strict-agreement bridge above; together the two
        // bridges pin the composition as the exact [`Ordering::then`]
        // lexicographic combinator on the paired (axial_ordering,
        // atomic_ordering) SIGNUM exits.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            if a.axial_ordering() == Ordering::Equal {
                assert_eq!(
                    a.axial_then_atomic_ordering(),
                    a.atomic_ordering(),
                    "axial_then_atomic_ordering() != atomic_ordering() on axial-balanced {a:?}",
                );
            }
        }
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_partitions_every_posture_into_exactly_one_leg() {
        // LEXICOGRAPHIC TRICHOTOMY EXHAUSTIVENESS pin — LOAD-BEARING
        // structural pin. Every posture returns EXACTLY ONE of the
        // three [`Ordering`] variants, and the returned variant
        // matches ONE of the composition legs: `Greater` iff axial
        // is Greater OR (axial Equal AND atomic Greater); `Less` iff
        // axial is Less OR (axial Equal AND atomic Less); `Equal`
        // iff both axial AND atomic are Equal. Proved structurally
        // by rustc's `match` exhaustiveness: any missing arm here
        // is a compile error, so the pin is a TYPE-level theorem of
        // the composed SIGNUM's exhaustiveness.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            let matches_partition_leg = match a.axial_then_atomic_ordering() {
                Ordering::Greater => {
                    a.axial_ordering() == Ordering::Greater
                        || (a.axial_ordering() == Ordering::Equal
                            && a.atomic_ordering() == Ordering::Greater)
                }
                Ordering::Less => {
                    a.axial_ordering() == Ordering::Less
                        || (a.axial_ordering() == Ordering::Equal
                            && a.atomic_ordering() == Ordering::Less)
                }
                Ordering::Equal => {
                    a.axial_ordering() == Ordering::Equal && a.atomic_ordering() == Ordering::Equal
                }
            };
            assert!(
                matches_partition_leg,
                "axial_then_atomic_ordering() leg mismatches (axial, atomic) partition on {a:?}",
            );
        }
    }

    #[test]
    fn resource_limits_axial_then_atomic_ordering_evaluates_at_compile_time_via_const_fn() {
        // Const-fn pin on the LEXICOGRAPHIC-COMPOSITION reading —
        // the composed [`Ordering`] verdict is evaluable in const
        // context so a caller can pin the exact whole-posture arm
        // at compile time as a build-break, including the LOAD-
        // BEARING atomic-tiebreaker promotion on the axially-
        // balanced regime witnessed by the truly-mixed fixtures.
        // Uses `matches!` because `Ordering` is not `PartialEq` in
        // a `const`-comparable form on stable Rust — `matches!` is
        // the const-context-legal shape, matching the const-fn
        // pattern the paired SIGNUM readings one PROJECTION-KIND
        // axis under.
        const _: () = assert!(matches!(
            EMPTY_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Greater,
        ));
        const _: () = assert!(matches!(
            UNBOUNDED_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Greater,
        ));
        const _: () = assert!(matches!(
            DEFAULT_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Less,
        ));
        const _: () = assert!(matches!(
            SPARSE_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Greater,
        ));
        const _: () = assert!(matches!(
            ENDPOINTS_ONLY_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Less,
        ));
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_preset_pins_atomic_short_circuits_on_polar_uniform_arms(
    ) {
        // ATOMIC-THEN-AXIAL LEXICOGRAPHIC SIGNUM preset pins — LOAD-
        // BEARING structural pin. The polar-uniform preset arms
        // (EMPTY, UNBOUNDED) both fire a strict atomic verdict on
        // their (6, 0) / (0, 6) atomic tally — EMPTY at atomic
        // `Greater` (bottom-uniform), UNBOUNDED at atomic `Less`
        // (top-uniform) — so both preset arms SHORT-CIRCUIT at the
        // atomic primary, NEVER consulting the axial tiebreaker.
        // The three interior-uniform postures (DEFAULT + both hand-
        // authored) all sit at the atomic `(0, 0)` balance corner
        // and defer to the axial tiebreaker; the axial reading fires
        // `Less` at 0-polar-6-interior on each, so the composed
        // reading pins at axial `Less`.
        assert_eq!(
            EMPTY_RESOURCE_LIMITS.atomic_then_axial_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            UNBOUNDED_RESOURCE_LIMITS.atomic_then_axial_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            DEFAULT_RESOURCE_LIMITS.atomic_then_axial_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            HAND_AUTHORED_MID_POSTURE.atomic_then_axial_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            HAND_AUTHORED_OTHER_POSTURE.atomic_then_axial_ordering(),
            Ordering::Less,
        );
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_truly_mixed_fires_atomic_short_circuit_on_bottom_carrying_fixtures(
    ) {
        // LOAD-BEARING atomic-primary short-circuit pin on truly-
        // mixed fixtures. All three shipped truly-mixed fixtures
        // carry a bottom-majority atomic tally (positive atomic
        // count, zero top), so all three fire atomic `Greater` and
        // the atomic-primary composition SHORT-CIRCUITS to
        // `Ordering::Greater` on each — the axial verdicts (Equal
        // on the two 3-3 fixtures, Less on ENDPOINTS_ONLY_BOTTOM
        // at 2-polar-4-interior) are DISCARDED. This is the LOAD-
        // BEARING contrast with `axial_then_atomic_ordering` on
        // the ENDPOINTS_ONLY_BOTTOM posture: axial-primary returns
        // `Less` (via axial short-circuit); atomic-primary returns
        // `Greater` (via atomic short-circuit); the primary-key
        // axis names which arm dominates on the disagreement.
        assert_eq!(
            SPARSE_BOTTOM_POSTURE.atomic_then_axial_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE.atomic_then_axial_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            ENDPOINTS_ONLY_BOTTOM_POSTURE.atomic_then_axial_ordering(),
            Ordering::Greater,
        );
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_agrees_with_atomic_when_atomic_non_equal() {
        // ATOMIC-STRICT-AGREEMENT bridge — LOAD-BEARING structural
        // pin. On every posture whose atomic SIGNUM reading fires
        // a strict verdict (`Greater` or `Less`), the composed
        // reading returns that same verdict — the axial tiebreaker
        // is NOT consulted. Pins the atomic-primary composition as
        // SHORT-CIRCUITING on the first non-`Equal` argument,
        // matching the std-canonical [`Ordering::then`] semantics
        // the const-fn body inlines. Mirror of the axial-primary
        // strict-agreement bridge one PRIMARY-KEY axis over.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            if a.atomic_ordering() != Ordering::Equal {
                assert_eq!(
                    a.atomic_then_axial_ordering(),
                    a.atomic_ordering(),
                    "atomic_then_axial_ordering() != atomic_ordering() on atomic-strict {a:?}",
                );
            }
        }
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_equals_axial_when_atomic_equal() {
        // ATOMIC-EQUAL-USE-AXIAL bridge — LOAD-BEARING structural
        // pin dual. On every posture whose atomic SIGNUM reading
        // fires `Equal`, the composed reading defers to the axial
        // SIGNUM verdict — the axial reading BECOMES the whole-
        // posture verdict on the atomically-balanced regime.
        // Complements the atomic-strict-agreement bridge above;
        // together the two bridges pin the atomic-primary
        // composition as the exact [`Ordering::then`] lexicographic
        // combinator on the paired (atomic_ordering, axial_ordering)
        // SIGNUM exits. Mirror of the axial-primary equal-use-atomic
        // bridge one PRIMARY-KEY axis over.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            if a.atomic_ordering() == Ordering::Equal {
                assert_eq!(
                    a.atomic_then_axial_ordering(),
                    a.axial_ordering(),
                    "atomic_then_axial_ordering() != axial_ordering() on atomic-balanced {a:?}",
                );
            }
        }
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_partitions_every_posture_into_exactly_one_leg() {
        // LEXICOGRAPHIC TRICHOTOMY EXHAUSTIVENESS pin — LOAD-BEARING
        // structural pin. Every posture returns EXACTLY ONE of the
        // three [`Ordering`] variants, and the returned variant
        // matches ONE of the composition legs: `Greater` iff atomic
        // is Greater OR (atomic Equal AND axial Greater); `Less` iff
        // atomic is Less OR (atomic Equal AND axial Less); `Equal`
        // iff both atomic AND axial are Equal (this joint-Equal
        // corner is the ONE cell both lexicographic compositions
        // AGREE on identically — order-of-composition-invariant).
        // Proved structurally by rustc's `match` exhaustiveness: any
        // missing arm here is a compile error, so the pin is a
        // TYPE-level theorem of the atomic-primary composed SIGNUM's
        // exhaustiveness. Mirror of the axial-primary exhaustiveness
        // pin one PRIMARY-KEY axis over.
        let postures = [
            EMPTY_RESOURCE_LIMITS,
            DEFAULT_RESOURCE_LIMITS,
            UNBOUNDED_RESOURCE_LIMITS,
            HAND_AUTHORED_MID_POSTURE,
            HAND_AUTHORED_OTHER_POSTURE,
            SPARSE_BOTTOM_POSTURE,
            CONTIGUOUS_INTERIOR_BOTTOM_POSTURE,
            ENDPOINTS_ONLY_BOTTOM_POSTURE,
        ];
        for a in postures {
            let matches_partition_leg = match a.atomic_then_axial_ordering() {
                Ordering::Greater => {
                    a.atomic_ordering() == Ordering::Greater
                        || (a.atomic_ordering() == Ordering::Equal
                            && a.axial_ordering() == Ordering::Greater)
                }
                Ordering::Less => {
                    a.atomic_ordering() == Ordering::Less
                        || (a.atomic_ordering() == Ordering::Equal
                            && a.axial_ordering() == Ordering::Less)
                }
                Ordering::Equal => {
                    a.atomic_ordering() == Ordering::Equal && a.axial_ordering() == Ordering::Equal
                }
            };
            assert!(
                matches_partition_leg,
                "atomic_then_axial_ordering() leg mismatches (atomic, axial) partition on {a:?}",
            );
        }
    }

    #[test]
    fn resource_limits_atomic_then_axial_ordering_diverges_from_axial_then_atomic_on_primary_key_disagreement_fixtures(
    ) {
        // PRIMARY-KEY DIVERGENCE pin — LOAD-BEARING structural pin.
        // On the two shipped fixtures where the (axial, atomic)
        // SIGNUM pair DISAGREES on strict-vs-tie or on strict-arm
        // identity, the (axial-primary, atomic-primary) composition
        // pair returns DIFFERENT verdicts, witnessing the primary-
        // key axis as a proper structural split rather than a
        // same-function alias.
        //
        // UNBOUNDED: axial `Greater` (polar-uniform-top), atomic
        // `Less` (0-bottom-6-top) — the primary-key wins:
        // axial-primary short-circuits to axial `Greater`;
        // atomic-primary short-circuits to atomic `Less`.
        assert_eq!(
            UNBOUNDED_RESOURCE_LIMITS.axial_then_atomic_ordering(),
            Ordering::Greater,
        );
        assert_eq!(
            UNBOUNDED_RESOURCE_LIMITS.atomic_then_axial_ordering(),
            Ordering::Less,
        );
        // ENDPOINTS_ONLY_BOTTOM: axial `Less` (2-polar-4-interior),
        // atomic `Greater` (2-bottom-0-top) — same primary-key
        // winner pattern with the arm identities swapped:
        // axial-primary short-circuits to axial `Less`;
        // atomic-primary short-circuits to atomic `Greater`.
        assert_eq!(
            ENDPOINTS_ONLY_BOTTOM_POSTURE.axial_then_atomic_ordering(),
            Ordering::Less,
        );
        assert_eq!(
            ENDPOINTS_ONLY_BOTTOM_POSTURE.atomic_then_axial_ordering(),
            Ordering::Greater,
        );
    }

